<style>
    :root{--bg:#07111f;--surface:#0d1a2b;--surface2:#122238;--line:rgba(255,255,255,.09);--text:#f6f8fb;--muted:#9babbe;--accent:#3478f6;--accent-soft:#8ab3ff;--ok:#3ecf8e}
    *{box-sizing:border-box}html{background:var(--bg);scroll-behavior:smooth}body{margin:0;color:var(--text);background:radial-gradient(900px 440px at 85% -10%,rgba(52,120,246,.18),transparent 60%),var(--bg);font-family:"Cairo","Segoe UI",Tahoma,sans-serif;line-height:1.7}
    a{color:inherit}img{max-width:100%}.wrap{width:min(1120px,calc(100% - 32px));margin:auto}.hero{padding:max(48px,env(safe-area-inset-top)) 0 32px;border-bottom:1px solid var(--line)}
    .identity{display:grid;grid-template-columns:112px 1fr;gap:24px;align-items:center}.avatar{width:112px;height:112px;border-radius:30px;object-fit:cover;background:var(--surface2);border:1px solid var(--line)}
    h1{font-size:clamp(30px,5vw,52px);line-height:1.15;margin:0 0 8px;letter-spacing:-.03em}.headline{font-size:clamp(16px,2.2vw,21px);color:#d7e0ec;margin:0}.muted{color:var(--muted)}
    .chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.chip{border:1px solid var(--line);background:rgba(255,255,255,.035);padding:7px 12px;border-radius:999px;font-size:13px}
    section{padding:42px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:18px}.section-head h2{font-size:26px;margin:0}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px;align-items:start}
    .project{grid-column:span 6;overflow:hidden;border:1px solid var(--line);border-radius:24px;background:linear-gradient(180deg,var(--surface2),var(--surface));box-shadow:0 18px 60px rgba(0,0,0,.16)}
    .project.featured{grid-column:span 12}.cover{display:block;position:relative;background:#0a1524;text-decoration:none}.cover img{display:block;width:100%;height:auto;max-height:620px;object-fit:contain;margin:auto}.cover-count{position:absolute;inset-block-end:12px;inset-inline-end:12px;background:rgba(7,17,31,.82);border:1px solid var(--line);border-radius:999px;padding:3px 10px;font-size:12px}
    .media-stack{display:grid;gap:12px}.media-stack.compact{gap:1px;background:var(--line)}.asset{display:block;width:100%;height:auto;background:#0a1524;border:0}.zoom{display:block;cursor:zoom-in;background:#0a1524}.zoom img{display:block;width:auto;max-width:100%;height:auto;max-height:90vh;margin:auto}
    figure{margin:0}figcaption{color:var(--muted);font-size:13px;padding:8px 2px 0}
    .video{position:relative;width:100%;aspect-ratio:16/9;background:#0a1524;overflow:hidden}.video iframe{position:absolute;inset:0;width:100%;height:100%;border:0}.video-play{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-decoration:none}.video-play img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.play-icon{position:relative;display:grid;place-items:center;width:68px;height:68px;border-radius:50%;background:rgba(7,17,31,.78);border:1px solid rgba(255,255,255,.3);font-size:24px;padding-inline-start:4px}
    .project-body{padding:22px}.project h3{font-size:21px;margin:0 0 7px}.project h3 a{text-decoration:none}.eyebrow{font-size:12px;color:var(--accent-soft);margin-bottom:7px}.summary{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
    .tools{display:flex;gap:6px;flex-wrap:wrap;margin-top:16px}.tools span{font-size:12px;color:var(--muted);background:rgba(255,255,255,.045);padding:5px 9px;border-radius:8px}
    .verified{display:inline-flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px;padding:5px 12px;border-radius:999px;background:rgba(62,207,142,.12);border:1px solid rgba(62,207,142,.35);color:#c9f5df;font-size:13px;font-weight:700}.verified-mark{display:grid;place-items:center;width:18px;height:18px;border-radius:50%;background:var(--ok);color:#06231a;font-size:12px}.verified a{color:#fff;font-weight:600}
    .actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.button{display:inline-flex;align-items:center;min-height:44px;padding:9px 18px;border-radius:12px;background:var(--accent);color:#fff;font-weight:700;text-decoration:none}.button.secondary{background:rgba(255,255,255,.06);border:1px solid var(--line)}
    .back{display:inline-flex;align-items:center;gap:10px;text-decoration:none;color:var(--muted)}.back img{width:36px;height:36px;border-radius:12px;object-fit:cover}
    .project-page h1{font-size:clamp(28px,4.4vw,46px)}.facts{display:flex;gap:8px 18px;flex-wrap:wrap;color:var(--muted);font-size:14px;margin-top:10px}.description{max-width:760px;font-size:17px;color:#d7e0ec}
    footer{border-top:1px solid var(--line);padding:26px 0 max(30px,env(safe-area-inset-bottom));color:var(--muted);font-size:13px}
    .report{margin-top:16px;max-width:560px}.report summary{cursor:pointer}.report label{display:block;margin:12px 0 4px}.report textarea,.report input{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text);font:inherit}.report button{margin-top:12px;padding:10px 20px;border:0;border-radius:8px;background:var(--accent);color:white;font:inherit}.report-status{color:var(--text)}
    .lightbox{width:100vw;height:100dvh;max-width:none;max-height:none;margin:0;padding:0;border:0;background:rgba(3,8,15,.94);color:var(--text)}.lightbox::backdrop{background:rgba(3,8,15,.94)}.lightbox[open]{display:flex;align-items:center;justify-content:center}.lightbox figure{display:flex;flex-direction:column;align-items:center;max-width:100%;max-height:100%;padding:56px 64px 24px}.lightbox img{max-width:100%;max-height:calc(100dvh - 120px);object-fit:contain}.lightbox figcaption{text-align:center}
    .lb-button{position:absolute;display:grid;place-items:center;width:48px;height:48px;border-radius:50%;border:1px solid var(--line);background:rgba(13,26,43,.9);color:#fff;font:inherit;font-size:26px;cursor:pointer}.lb-close{top:12px;inset-inline-end:12px}.lb-prev{top:50%;inset-inline-start:12px;transform:translateY(-50%)}.lb-next{top:50%;inset-inline-end:12px;transform:translateY(-50%)}.lb-count{position:absolute;top:22px;inset-inline-start:20px;font-size:13px;color:var(--muted)}.lb-button[hidden]{display:none}
    :focus-visible{outline:2px solid var(--accent-soft);outline-offset:2px}
    @media(max-width:720px){.wrap{width:min(100% - 24px,1120px)}.identity{grid-template-columns:76px 1fr;gap:15px}.avatar{width:76px;height:76px;border-radius:22px}.project,.project.featured{grid-column:span 12}.hero{padding-top:max(28px,env(safe-area-inset-top))}section{padding:30px 0}.project{border-radius:20px}.lightbox figure{padding:56px 8px 16px}.lb-prev,.lb-next{top:auto;bottom:14px;transform:none}}
    @media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style>
